import{_ as t,o as i,c as a,a2 as n}from"./chunks/framework.Cm6XCzck.js";const h=JSON.parse('{"title":"9. Three-Valued Governance Interpretation","description":"","frontmatter":{},"headers":[],"relativePath":"en/publications/implementation-case-i0.8/part-03.md","filePath":"en/publications/implementation-case-i0.8/part-03.md","lastUpdated":1786346403000}'),o={name:"en/publications/implementation-case-i0.8/part-03.md"};function r(d,e,l,c,s,p){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="_9-three-valued-governance-interpretation" tabindex="-1">9. Three-Valued Governance Interpretation <a class="header-anchor" href="#_9-three-valued-governance-interpretation" aria-label="Permalink to &quot;9. Three-Valued Governance Interpretation&quot;">​</a></h1><p>TMPA keeps semantic judgment separate from view classification:</p><table tabindex="0"><thead><tr><th>Judgment</th><th>Typical view</th><th>Meaning</th></tr></thead><tbody><tr><td><code>valid</code></td><td>authoritative</td><td>Required evidence and applicable rules establish the conclusion.</td></tr><tr><td><code>invalid</code></td><td>quarantined / rejected</td><td>A deterministic violation excludes the affected evidence or action.</td></tr><tr><td><code>undetermined</code></td><td>partial / disputed / pending_human</td><td>Evidence is missing or conflicting, or an authorized human decision is still required.</td></tr></tbody></table><p>I0.8 makes the separation observable. A wrong-type or self-issued approval is preserved but cannot satisfy C07. A missing reference in C09 leaves the dependent claim undetermined rather than false or complete. An unauthorized C12 resolution remains evidence but is invalid as a resolving act. Integrity failure in C08 quarantines covered content while preserving its source record.</p><h1 id="_10-evidence-integrity-and-publication-preflight" tabindex="-1">10. Evidence Integrity and Publication Preflight <a class="header-anchor" href="#_10-evidence-integrity-and-publication-preflight" aria-label="Permalink to &quot;10. Evidence Integrity and Publication Preflight&quot;">​</a></h1><p>The formal archive contains 195 files; 194 payload files are covered by its internal SHA-256 manifest. Its outer SHA-256 is <code>3c34514089f08f5957d806f900ab31af1cdae94c08f31a5da046f451b5884fe9</code>. Independent publication preflight verified:</p><ul><li>ZIP structural integrity and ASCII-only entry names;</li><li>strict UTF-8 decoding for every file;</li><li>137 JSON files and 11 JSONL records;</li><li>194/194 internal SHA-256 entries;</li><li>byte identity for all seven official S0.6 inputs;</li><li>schema-valid C01–C14 result envelopes;</li><li>product Reader invocation without Reference Reader substitution;</li><li>a self-contained reproducer result of 14/14 PASS.</li></ul><p>The initial 2026-08-09 candidate archive is not published. It contained semantically identical but checkout-converted CRLF copies of the official inputs, an incorrect manifest-count statement, and no self-contained public rerun path. The corrected 2026-08-10 archive replaces it as the sole I0.8 formal package.</p><h1 id="_11-limitations" tabindex="-1">11. Limitations <a class="header-anchor" href="#_11-limitations" aria-label="Permalink to &quot;11. Limitations&quot;">​</a></h1><ol><li>The product and full-suite evidence is author-run; no independent organization has certified or adopted the implementation.</li><li>The CodeFlowMu implementation commit is local and is not represented as a public release, tag, or complete public source tree.</li><li>The public reproducer exposes the conformance slice, not the entire private CodeFlowMu application or its full Runtime/Shell environment.</li><li>Runtime retains one skipped test; the FCoP reference implementation retains two migrated-layout historical-example skips.</li><li>C11 evaluates a fixed fixture set and its declared permutations; it is not a formal proof over arbitrary graphs or hostile platforms.</li><li>C08 demonstrates governance-object integrity handling, not model truthfulness, identity authentication, installer protection, or Byzantine resilience.</li><li>Full-suite performance, representative SME burden, comparative baselines, and independent deployment remain open empirical questions.</li><li>WP-13 is a bounded governance case, not a hallucination-elimination benchmark.</li></ol><h1 id="_12-claim-ledger" tabindex="-1">12. Claim Ledger <a class="header-anchor" href="#_12-claim-ledger" aria-label="Permalink to &quot;12. Claim Ledger&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Claim</th><th>I0.8 disposition</th></tr></thead><tbody><tr><td>TMPA Core S0.6 defines C01–C14</td><td><strong>Specified</strong></td></tr><tr><td>CodeFlowMu V1.6.0 contains corresponding product mechanisms</td><td><strong>Implemented</strong></td></tr><tr><td>The fixed product bundle records 14/14 PASS</td><td><strong>Demonstrated</strong></td></tr><tr><td>The self-contained conformance slice can be publicly rerun</td><td><strong>Demonstrated</strong></td></tr><tr><td>The complete private CodeFlowMu application is publicly reproducible</td><td><strong>Not claimed</strong></td></tr><tr><td>The result has been independently certified or adopted</td><td><strong>Not demonstrated</strong></td></tr><tr><td>WP-13 proves hallucination elimination</td><td><strong>Prohibited conclusion</strong></td></tr></tbody></table><h1 id="_13-engineering-conclusion" tabindex="-1">13. Engineering Conclusion <a class="header-anchor" href="#_13-engineering-conclusion" aria-label="Permalink to &quot;13. Engineering Conclusion&quot;">​</a></h1><p>I0.8 advances the Implementation Case from an exact S0.5 product result to an exact-input S0.6 product result. CodeFlowMu V1.6.0 passes all fourteen mandatory criteria while directly exposing the S0.6 changes in provenance retention, approval authority, and locale-independent reconstruction. A self-contained reproducer narrows the gap between author-local product evidence and public inspection without misrepresenting the private full application as open or independently validated.</p><p>The result strengthens the engineering evidence for TMPA&#39;s implementability, not the logical truth of the theory. TMPA theory guides the system design, Core S0.6 fixes the evaluated requirements, FCoP supplies the collaboration and evidence protocol, CodeFlowMu is the application execution and consumption layer under test, and WP-13 is a bounded field case. Independent adoption and broader empirical evaluation remain future work.</p><h1 id="artifact-availability" tabindex="-1">Artifact Availability <a class="header-anchor" href="#artifact-availability" aria-label="Permalink to &quot;Artifact Availability&quot;">​</a></h1><p>The formal I0.8 archive is <a href="/joinwell52/evidence/tmpa/i0.8/tmpa-i0.8-codeflowmu-v1.6.0-s0.6-evidence-20260810.zip">tmpa-i0.8-codeflowmu-v1.6.0-s0.6-evidence-20260810.zip</a>. The adjacent file <code>tmpa-i0.8-codeflowmu-v1.6.0-s0.6-evidence-20260810.zip.sha256</code> records <code>3c34514089f08f5957d806f900ab31af1cdae94c08f31a5da046f451b5884fe9</code>.</p><p>I0.7 and its V1.4.1/S0.5 archive remain available at their versioned paths. The rejected I0.8 candidate is not part of the public publication set. Git history is the publication history; no parallel paper database has editorial authority.</p><h1 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h1><p>[1] TMPA Project. “TMPA Core Specification S0.6,” commit <code>8989657e8fde6d2e55d7606ae0adacac14fec760</code>. GitHub, 2026.</p><p>[2] TMPA Project. “TMPA Architecture Paper A0.9.” GitHub, 2026.</p><p>[3] FCoP Project. “FCoP — File-based Coordination Protocol,” reference implementation commit <code>da79dfefd99f597c9e422ce9edec22157f915a21</code>. GitHub, 2026.</p><p>[4] CodeFlowMu Project. “CodeFlowMu V1.6.0 S0.6 Product Conformance,” implementation commit <code>62440a526a99d2fe55019d8bb95ad2425569fcb4</code>, 2026.</p><p>[5] TMPA Project. “I0.8 CodeFlowMu V1.6.0 S0.6 Evidence,” package <code>tmpa-i0.8-codeflowmu-v1.6.0-s0.6-evidence-20260810</code>, 2026.</p><p>[6] CodeFlowMu Project. “WP-13 Multi-Agent Fact-Check Publication Evidence V3,” 2026.</p><p>[7] CodeFlowMu Project. “CodeFlowMu V1.4–V1.5 TMPA × FCoP × Application Unified Architecture,” <code>docs/TMPA-GOVERNANCE.md</code>. GitHub, 2026. <code>https://github.com/joinwell52-AI/codeflowmu/blob/main/docs/TMPA-GOVERNANCE.md</code>.</p>',26)])])}const m=t(o,[["render",r]]);export{h as __pageData,m as default};
